  x: zod.z.number().optional().describe("X position in points"),
  y: zod.z.number().optional().describe("Y position in points"),
  width: zod.z.number().optional().describe("Width in points"),
  height: zod.z.number().optional().describe("Height in points"),
  text: zod.z.string().optional().describe("Text content"),
  fontSize: zod.z.number().optional().describe("Font size in points"),
  fontFamily: zod.z.string().optional().describe("Font family name"),
  fontColor: zod.z.string().optional().describe("Font color (hex)"),
  bold: zod.z.boolean().optional().describe("Bold text"),
  italic: zod.z.boolean().optional().describe("Italic text"),
  underline: zod.z.boolean().optional().describe("Underline text"),
  alignment: zod.z.enum(["left", "center", "right", "justify"]).optional().describe("Text alignment"),
  shapeType: zod.z.string().optional().describe('Shape type (e.g. "rect", "ellipse")'),
  fillColor: zod.z.string().optional().describe("Fill color (hex)"),
  strokeColor: zod.z.string().optional().describe("Stroke color (hex)"),
  strokeWidth: zod.z.number().optional().describe("Stroke width in points"),
  imageData: zod.z.string().optional().describe("Image as base64 data URL"),
  altText: zod.z.string().optional().describe("Alt text for accessibility"),
  rows: zod.z.number().int().min(1).optional().describe("Number of table rows"),
  columns: zod.z.number().int().min(1).optional().describe("Number of table columns"),
  cellData: zod.z.array(zod.z.array(zod.z.string())).optional().describe("Table cell data as 2D array"),
  headerRow: zod.z.boolean().optional().describe("Style first row as header"),
  startArrow: zod.z.string().optional().describe("Start arrow type"),
  endArrow: zod.z.string().optional().describe("End arrow type"),
